import{_ as r,o as a,c as t,a3 as s}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"Streaming research interface","description":"","frontmatter":{},"headers":[],"relativePath":"project/streaming.md","filePath":"project/streaming.md","lastUpdated":1794433168000}'),n={name:"project/streaming.md"};function o(i,e,c,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="streaming-research-interface" tabindex="-1">Streaming research interface <a class="header-anchor" href="#streaming-research-interface" aria-label="Permalink to &quot;Streaming research interface&quot;">​</a></h1><p><strong>Proposed product behavior.</strong> VitePress is the documentation interface. SvelteKit/TypeScript remains the proposed application client, with a Rust API and leased model workers.</p><h2 id="four-connected-views" tabindex="-1">Four connected views <a class="header-anchor" href="#four-connected-views" aria-label="Permalink to &quot;Four connected views&quot;">​</a></h2><p><strong>Chat</strong> streams answers and preserves clear outcomes. <strong>Evidence</strong> opens exact spans, source independence and claim assessments. <strong>Jobs</strong> shows queue, progress, blocked capabilities and review state. <strong>Review</strong> compares an immutable proposal with published knowledge and requires explicit authorization.</p><p>Published knowledge is the default. Authorization applies before retrieval and evidence selection, not just after generation. A model never authorizes its own tools, draft access or publication.</p><h2 id="durable-work-direct-browser-stream" tabindex="-1">Durable work, direct browser stream <a class="header-anchor" href="#durable-work-direct-browser-stream" aria-label="Permalink to &quot;Durable work, direct browser stream&quot;">​</a></h2><p>The API admits a run through the private store and obtains a durable run identity before provider work starts. A leased worker performs bounded retrieval/generation and records output batches and outcomes. The API delivers authorized committed events over SSE. The browser connection is not the only owner of the run.</p><p>Keep transactions short. Do not hold one open during inference. Batching should reduce overhead, with latency measured rather than promised. Explicitly distinguish committed/replayable answer text from transient UI progress; never claim an uncommitted tail survived a crash.</p><p>Proposed full event vocabulary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run.started</span></span>
<span class="line"><span>retrieval.evidence_selected</span></span>
<span class="line"><span>answer.delta / answer.citation</span></span>
<span class="line"><span>run.ended { outcome: complete | incomplete | refused | failed | cancelled | interrupted }</span></span>
<span class="line"><span>job.progress / review.required / library.published</span></span></code></pre></div><p>Versioned envelopes carry run/job identity, sequence/cursor, schema and library revision where applicable. The <a href="./../engineering/examples#stream-framing">small stream lab</a> uses abbreviated started/delta/completed names only to test framing; it is not the final application schema.</p><h2 id="required-lifecycle" tabindex="-1">Required lifecycle <a class="header-anchor" href="#required-lifecycle" aria-label="Permalink to &quot;Required lifecycle&quot;">​</a></h2><p>A request key prevents duplicate admission; changed input with the same key is a conflict. Reconnect requests stored state/events for the existing run, not a new generation. Each subscription and evidence fetch is reauthorized. Expired history returns a scoped snapshot/resynchronization response.</p><p>Stop is an explicit cancellation command independent of a blocked output send. Preserve committed partial text. Worker/API termination may leave a run interrupted; a paid inference that already produced output is not silently restarted. A user-approved retry creates a distinguishable new attempt/run and provenance trail.</p><p>Provider outcomes are normalized before reaching the browser. A stream sentinel, socket close or EOF is not proof of a complete answer. Length limits and refusals remain visible outcomes. Local canned/mock behavior is explicitly selected and labelled.</p><h2 id="correctness-and-safety" tabindex="-1">Correctness and safety <a class="header-anchor" href="#correctness-and-safety" aria-label="Permalink to &quot;Correctness and safety&quot;">​</a></h2><p>Incremental UTF-8 decoding must preserve characters split across reads. Buffer only within configured bounds and parse complete frames. Reject invalid event order, identity changes, unsupported terminal states and malformed payloads. Preserve the workshop&#39;s session/view ownership checks when adapting it to Svelte.</p><p>Render model text as untrusted content: constrain Markdown, leave raw HTML inert and restrict link schemes. Do not expose private source text, raw provider errors, credentials or administrative state through progress events. Authorized projections include limitations and durable cursor semantics.</p><h2 id="reuse-and-proof" tabindex="-1">Reuse and proof <a class="header-anchor" href="#reuse-and-proof" aria-label="Permalink to &quot;Reuse and proof&quot;">​</a></h2><p>The <a href="./../reuse/source-audit">source audit</a> identifies exact gateway functions and workshop consumer code. Keep Ordo&#39;s provider separation and timed batching; repair separate-chunk lossy decoding and serial receive/generation handling. The workshop&#39;s incremental decoder is a behavior reference, not a reason to adopt its entire backend.</p><p>Test through actual HTTPS: first-event delivery, idle heartbeats, slow clients, cancellation during blocked sends, malformed Unicode, reconnect, account changes, duplicate requests and citations after a new library publication. A synthetic decoder pass is not proxy or browser proof. <a href="https://html.spec.whatwg.org/multipage/server-sent-events.html" target="_blank" rel="noreferrer">SSE protocol reference</a>.</p>`,21)])])}const m=r(n,[["render",o]]);export{h as __pageData,m as default};
